check("linkable ring tool now cross-points to the blind signature in tool 36", html.includes("Tool 36 below turns the whole question around"));
check("blind signature tool present", html.includes('id="blind-sig"') && html.includes('id="blind-commit"') && html.includes('id="blind-request"') && html.includes('id="blind-sign"') && html.includes('id="blind-unblind"') && html.includes('id="blind-unblind-out"'));
check("blind signature tool honestly labelled a real signature but not the format any chain or wallet checks", html.includes("Signed without seeing") && html.includes("David Chaum") && html.includes("not the signature format any chain or wallet checks"));
check("blind signature tool honestly states the signer endorses sight unseen, for tokens not statements", html.includes("endorsing sight unseen") && html.includes("never for statements"));
check("blind signature tool honestly states the ROS attack on parallel blind Schnorr sessions", html.includes("ROS attack on blind Schnorr") && html.includes("answer one session at a time"));
